import math
from ladder import series, parallel, divider, r2r_ladder

def test_series_parallel():
    assert series(100, 200, 300) == 600
    assert math.isclose(parallel(100, 100), 50)
    assert math.isclose(parallel(100, 200, 300), 54.5454545, rel_tol=1e-6)

def test_divider():
    assert math.isclose(divider(vin=9, r_top=6000, r_bottom=3000), 3.0)

def test_r2r_ladder_msb():
    assert math.isclose(r2r_ladder(bits=[1,0,0,0], vref=8.0), 4.0)

def test_r2r_ladder_full():
    assert math.isclose(r2r_ladder(bits=[1,1,1,1], vref=8.0), 7.5)

def test_r2r_matches_binary_weighting():
    for n in range(16):
        bits = [int(b) for b in format(n, '04b')]
        assert math.isclose(r2r_ladder(bits, 8.0), 8.0*n/16)

r2r_ladder must actually solve the R-2R network (nodal analysis or systematic reduction), not just apply the binary formula — add an internal assertion or comment showing the network solve, and verify with pytest that all tests pass.

